import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
experiments = {}
for i in range(1, 8):
    varname = f'experiment_{i}_csv'
    df = pd.read_csv(globals()[varname])
    experiments[i] = df
    print(f"Experiment {i}: {df.columns.tolist()} shape={df.shape}")
    print(df.describe().round(3))
    print()

# Check if any experiments have intervention columns (e.g. ChamberPressure was set)
for i, df in experiments.items():
    if 'ChamberPressure' in df.columns and 'WaferYield' in df.columns:
        print(f"Exp {i}: Corr(WaferYield, ChamberPressure) = {df['WaferYield'].corr(df['ChamberPressure']):.3f}")
    if 'DefectDensity' in df.columns and 'WaferYield' in df.columns:
